#include <stdio.h>

struct Point {
    int x, y;
};

int main() {
    struct Point p = {10, 20};
    printf("Point coordinates: (%d, %d)\n", p.x, p.y);
    return 0;
}

#include <stdio.h>
#include <string.h>

struct Book {
    char title[50];
    int pages;
};

int main() {
    struct Book b;
    strcpy(b.title, "The C Programming Language");
    b.pages = 272;
    printf("Book Title: %s\nNumber of Pages: %d\n", b.title, b.pages);
    return 0;
}

#include <stdio.h>

struct Student {
    int id;
    char name[30];
};

int main() {
    struct Student students[3] = {
        {101, "Alice"},
        {102, "Bob"},
        {103, "Charlie"}
    };
    for (int i = 0; i < 3; i++) {
        printf("Student %d: ID %d, Name %s\n", i+1, students[i].id, students[i].name);
    }
    return 0;
}

#include <stdio.h>

struct Rectangle {
    float length, width;
};

int main() {
    struct Rectangle myRect;
    struct Rectangle *ptr = &myRect;
    ptr->length = 7.5f;
    ptr->width = 7.0f;
    float area = ptr->length * ptr->width;
    printf("Rectangle area after modification via pointer: %.2f\n", area);
    return 0;
}

#include <stdio.h>
#include <string.h>

struct Date {
    int day, month, year;
};
struct Person {
    char name[30];
    struct Date dob;
};

int main() {
    struct Person p;
    strcpy(p.name, "John Doe");
    p.dob.day = 15; p.dob.month = 8; p.dob.year = 1990;
    printf("Name: %s, DOB: %02d/%02d/%d\n", p.name, p.dob.day, p.dob.month, p.dob.year);
    return 0;
}

#include <stdio.h>

struct Complex {
    float real, imag;
};

struct Complex add(struct Complex a, struct Complex b) {
    struct Complex res;
    res.real = a.real + b.real;
    res.imag = a.imag + b.imag;
    return res;
}

int main() {
    struct Complex c1, c2, sum;
    scanf("%f%f", &c1.real, &c1.imag);
    scanf("%f%f", &c2.real, &c2.imag);
    sum = add(c1, c2);
    printf("Sum of complex numbers: %.2f + %.2fi\n", sum.real, sum.imag);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Product {
    int id;
    float price;
};

int main() {
    int N;
    scanf("%d", &N);
    struct Product *products = (struct Product*)malloc(N * sizeof(struct Product));
    for (int i = 0; i < N; i++) scanf("%d%f", &products[i].id, &products[i].price);
    printf("Product Inventory:\n");
    for (int i = 0; i < N; i++) printf("Product ID: %d, Price: $%.2f\n", products[i].id, products[i].price);
    free(products);
    printf("Memory for products freed.\n");
    return 0;
}

#include <stdio.h>

struct Employee {
    int id;
    char name[30];
    float salary;
};

void displayEmployee(struct Employee e) {
    printf("Employee ID: %d, Name: %s, Salary: $%.2f\n", e.id, e.name, e.salary);
}

int main() {
    struct Employee employees[3] = {
        {101, "Alice", 50000.00f},
        {102, "Bob", 60000.00f},
        {103, "Charlie", 75000.00f}
    };
    printf("--- Employee Details ---\n");
    for (int i = 0; i < 3; i++) displayEmployee(employees[i]);
    return 0;
}

#include <stdio.h>

struct Data {
    char c1;
    int i;
    char c2;
};

int main() {
    printf("Size of struct Data: %zu\n", sizeof(struct Data));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Book {
    char title[101], author[51];
    int year, available;
};

int main() {
    int n = 2, count = 0;
    struct Book *books = (struct Book*)malloc(n * sizeof(struct Book));
    for (int i = 0; i < 2; i++) {
        fgets(books[i].title, 101, stdin);
        books[i].title[strcspn(books[i].title, "\n")] = 0;
        fgets(books[i].author, 51, stdin);
        books[i].author[strcspn(books[i].author, "\n")] = 0;
        scanf("%d", &books[i].year);
        scanf("%d", &books[i].available);
        getchar();
        count++;
    }
    printf("--- Library Inventory ---\n");
    for (int i = 0; i < count; i++)
        printf("%d. Title: %s, Author: %s, Year: %d, Available: %s\n", i+1, books[i].title, books[i].author, books[i].year, books[i].available ? "Yes" : "No");
    free(books);
    return 0;
}
